(window.__APPSRC=window.__APPSRC||{})["xmvkq4zed--zzk-sj-prepa-ped-j7-sf3"]="{\n \"app\": \"xmvkq4zed\",\n \"id\": \"zzk-sj-prepa-ped-j7-sf3\",\n \"titre\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J7 (SF3)\",\n \"session\": \"J\",\n \"annee\": 2026,\n \"nq\": 52,\n \"nsuj\": 1,\n \"origines\": [\n  {\n   \"fichier\": \"prepa-de-2026/J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n   \"sha256\": \"c1e8c2d8402d3b954a7c6fc159ceb6b02b83cb88c53adce6ddd9268aa4b95034\"\n  }\n ],\n \"antennes\": [\n  {\n   \"name\": \"J DE PRÉPARATION AU D.E\",\n   \"slug\": \"j-preparation-de\",\n   \"session\": \"J\",\n   \"annee\": 2026,\n   \"existe\": true,\n   \"sujets\": [\n    {\n     \"name\": \"J Pédiatrie · Prépa D.E J7 (SF3) · reprend en grande partie le J1 et le J6 + nouvelles questions\",\n     \"slug\": \"prepa-ped-j7-sf3\",\n     \"pages\": \"\",\n     \"count\": 52,\n     \"session\": \"J\",\n     \"annee\": 2026,\n     \"matiere\": \"Pédiatrie\",\n     \"source\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n     \"questions\": [\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j7-sf3__0\",\n       \"num\": \"1\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"KJ est de 5 mois et orphelin de mère. Pour préparer son bol de lait infantile de 210 ml, j'utilise :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"4 mesurettes rases de lait\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"5 mesurettes rases de lait\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"6 mesurettes rases de lait\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"7 mesurettes rases de lait\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. 7 mesurettes rases de lait\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"Les laits en poudre maternisés se reconstituent à raison d'une mesurette rase (5 g) pour 30 ml d'eau. Pour un bol de 210 ml : 210 ÷ 30 = 7 mesurettes rases. Les autres nombres donneraient un lait trop dilué.\\n\\nSource : Cours de santé infantile L1 IDE-SFM, Diététique – « Les laits secs en poudre pour la diététique infantile »\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J7 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j7-sf3__1\",\n       \"num\": \"2\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Vous consultez l'enfant JP âgé de 36 mois. Son Z-score poids pour l'âge est en dessous de moins 3. Cela signifie que JP :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"a un poids normal pour son âge\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"est en surpoids pour son âge\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"est obèse pour son âge\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"a une malnutrition aiguë sévère\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. a une malnutrition aiguë sévère\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"Un Z-score inférieur à −3 traduit une malnutrition sévère ; parmi les propositions, seule « malnutrition aiguë sévère » correspond à un déficit (les autres décrivent un poids normal ou un excès). Remarque : dans le cours, la malnutrition aiguë sévère est définie par le Z-score poids/taille < −3 ; un Z-score poids/âge < −3 indique plutôt une insuffisance pondérale sévère.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Malnutrition de l'enfant », Diagnostic anthropométrique de la malnutrition\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J7 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j7-sf3__2\",\n       \"num\": \"3\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"PG, sexe masculin, 6 mois, 7 kg, a une diarrhée aiguë et boit avec avidité. Le pli cutané abdominal s'efface lentement et les yeux de PG sont enfoncés. Pour traiter PG, je lui administre durant les 4 premières heures de prise en charge :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"50 ml de SRO\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"350 ml de SRO\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"550 ml de SRO\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"525 ml de SRO\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. 525 ml de SRO\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"PG a des signes évidents de déshydratation (boit avec avidité, yeux enfoncés, pli qui s'efface lentement) : plan B, 75 ml/kg de SRO en 4 heures au centre de santé. 75 × 7 kg = 525 ml.\\n\\nSource : Livret de tableaux PCIMNE 0-5 ans, « Plan B : traiter les signes évidents de déshydratation avec une solution de SRO »\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J7 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j7-sf3__3\",\n       \"num\": \"4\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Nourrisson CB est âgé de 11 mois et pèse 11 kg. Il présente des signes sévères de déshydratation. J'administre durant les 5 heures suivant la 1re heure de traitement :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"770 ml de soluté\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"750 ml de soluté\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"700 ml de soluté\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"650 ml de soluté\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. 770 ml de soluté\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Signes sévères de déshydratation : plan C, 100 ml/kg de Ringer lactate. Chez le nourrisson de moins de 12 mois : 30 ml/kg en 1 heure puis 70 ml/kg en 5 heures. 70 × 11 kg = 770 ml.\\n\\nSource : Livret de tableaux PCIMNE 0-5 ans, « Plan C : traiter rapidement la déshydratation sévère »\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J7 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j7-sf3__4\",\n       \"num\": \"5\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"DF, garçon, est né à terme eutrophique. La sage-femme vous informe que DF pèse 3420 g au 3e jour de vie et qu'il a perdu 10 % de son poids de naissance. Je déduis que le poids de naissance de DF était de :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"3762 g\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"3580 g\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"3800 g\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"3250 g\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. 3800 g\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Après une perte de 10 %, le poids actuel représente 90 % du poids de naissance : 3420 ÷ 0,9 = 3800 g. Le cours rappelle que le nouveau-né perd environ le dixième de son poids les premiers jours (perte physiologique).\\n\\nSource : Cours de santé infantile L1 IDE-SFM, « Mensurations », Repères normaux de croissance somatique – Repères de gain de poids\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J7 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j7-sf3__5\",\n       \"num\": \"6\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Pour traiter le nouveau-né présentant une infection bactérienne néonatale tardive, le médecin utilise en priorité l'association :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Ampicilline + aminoside\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Chloramphénicol + aminoside\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Azithromycine + aminoside\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Ceftriaxone + aminoside\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. Ceftriaxone + aminoside\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"L'infection tardive (après J7) est due surtout à des germes de l'environnement (staphylocoques, bacilles Gram négatif) ; on utilise une céphalosporine de 3e génération associée à un aminoside. L'ampicilline + aminoside vise surtout les germes de l'infection précoce (streptocoque B, E. coli). Remarque : le module de néonatologie propose une trithérapie ampicilline + céfotaxime + gentamycine ; le choix « ceftriaxone + aminoside » relève de la pratique (explication partiellement hors cours du projet).\\n\\nSource : Module de néonatologie (Néonatalogie), Chapitre XII « Infections néonatales », Germes et Traitement\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J7 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j7-sf3__6\",\n       \"num\": \"7\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique — Nourrisson CB, fille, 3 mois, réside à Daloa, présente toux quinteuse, geignement. CB est nourrie au sein uniquement. Fréquence respiratoire 50 cycles/minute, diagnostic du médecin : bronchiolite.\",\n       \"text\": \"CB présente :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"4 données d'indépendance + 5 données de dépendance\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"7 données d'indépendance + 6 données de dépendance\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"6 données d'indépendance + 4 données de dépendance\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"5 données d'indépendance + 5 données de dépendance\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. 6 données d'indépendance + 4 données de dépendance\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Les données d'indépendance sont celles qui permettent de satisfaire les besoins sans aide (identification : nom, sexe, âge, lieu ; allaitement exclusif ; FR à 50/min, normale à cet âge) ; les données de dépendance sont les signes qui gênent un besoin (toux quinteuse, geignement, maladie…). La correction nationale retient 6 données d'indépendance et 4 de dépendance. Remarque : le cours donne la méthode mais pas le décompte exact pour ce cas ; le détail des 10 données n'est pas vérifiable dans les sources.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Diagnostic infirmier », Collecte des données – Analyse et interprétation des données\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J7 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j7-sf3__7\",\n       \"num\": \"8\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique — Nourrisson CB, fille, 3 mois, réside à Daloa, présente toux quinteuse, geignement. CB est nourrie au sein uniquement. Fréquence respiratoire 50 cycles/minute, diagnostic du médecin : bronchiolite.\",\n       \"text\": \"Le diagnostic infirmier est :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Perturbation des échanges gazeux reliée à un manque de force physique\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Dégagement inefficace des voies respiratoires relié à un manque de force physique\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Infection des poumons reliée à un manque de force physique\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Détresse respiratoire reliée à un manque de force physique\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Perturbation des échanges gazeux reliée à un manque de force physique\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Diagnostic infirmier = problème de dépendance + source de difficulté. La bronchiolite gêne les échanges gazeux ; chez un nourrisson de 3 mois, la source de difficulté est le manque de force physique (très jeune âge). « Infection des poumons » et « détresse respiratoire » sont des diagnostics médicaux, pas infirmiers. Remarque : « dégagement inefficace des voies respiratoires » (option B) pourrait aussi se discuter pour une bronchiolite encombrante ; la correction nationale retient la perturbation des échanges gazeux. Remarque : dans le sujet, chaque option de cette question est coupée sur deux lignes (ex. « Perturbation des échanges gazeux reliée à un » / « manque de force physique ») ; les morceaux ont été réunis.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Diagnostic infirmier », Diagnostic infirmier ; Glossaire du diagnostic infirmier\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J7 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j7-sf3__8\",\n       \"num\": \"9\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique — Nourrisson CB, fille, 3 mois, réside à Daloa, présente toux quinteuse, geignement. CB est nourrie au sein uniquement. Fréquence respiratoire 50 cycles/minute, diagnostic du médecin : bronchiolite.\",\n       \"text\": \"L'objectif de soins est de :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Maintenir la fréquence respiratoire dans les limites de la normale (18-30 cycles/min) dans un délai de 1 h après les soins\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Maintenir la fréquence respiratoire dans les limites de la normale (40-60 cycles/min) dans un délai de 1 h après les soins\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Maintenir sa fréquence respiratoire dans les limites de la normale (30-40 cycles/min) dans un délai de 1 h après les soins\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Maintenir sa fréquence respiratoire dans les limites de la normale (60-70 cycles/min) dans un délai de 1 h après les soins\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Maintenir la fréquence respiratoire dans les limites de la normale (40-60 cycles/min) dans un délai de 1 h après les soins\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"L'objectif doit viser une fréquence respiratoire normale pour l'âge : 40 à 60 cycles/min chez le jeune nourrisson. 18-30 correspond au grand enfant/adulte, 60-70 est une polypnée.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Nouveau-né normal », Diagnostic positif ; « Plan de soins », Objectifs de soins\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J7 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j7-sf3__9\",\n       \"num\": \"10\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'enfant qui souffre du kwashiorkor :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"est apathique et grognon\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"aime jouer et jeter les objets\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"réclame à manger et boire\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"est constipé mais a l'appétit\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. est apathique et grognon\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Dans le kwashiorkor, l'enfant est hostile, pleurnichard, indifférent et grognon, avec anorexie et refus de jouer. Réclamer à manger et garder l'appétit sont des signes du marasme.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Malnutrition de l'enfant », Diagnostic positif – Kwashiorkor\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J7 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j7-sf3__10\",\n       \"num\": \"11\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'infection bactérienne précoce du nouveau-né survient entre :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"J0 et J7 de vie\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"J7 et J14 de vie\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"J14 et J21 de vie\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"J21 et J28 de vie\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. J0 et J7 de vie\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"L'infection bactérienne précoce (materno-fœtale) survient avant le 7e jour de vie (J0-J7) ; l'infection tardive (postnatale) survient après le 7e jour, jusqu'à J28.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Infections bactériennes du nouveau-né », Introduction – Définition\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J7 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j7-sf3__11\",\n       \"num\": \"12\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"KL, 6 mois, sexe masculin, fièvre à 40 °C. Il tolère sa fièvre s'il a :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"un temps de recoloration cutané inférieur à 3 secondes\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"des extrémités froides\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"un teint grisâtre\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"un geignement\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. un temps de recoloration cutané inférieur à 3 secondes\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Un temps de recoloration cutanée inférieur à 3 secondes est normal et témoigne d'une bonne tolérance. Extrémités froides, teint grisâtre et gémissements/cri plaintif sont des signes de mauvaise tolérance de la fièvre.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Fièvre de l'enfant », Diagnostic étiologique – Examen physique\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J7 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j7-sf3__12\",\n       \"num\": \"13\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'enfant né à terme eutrophique, allaité et correctement nourri, quadruple son poids de naissance à :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"24 mois\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"9 mois\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"12 mois\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"3 mois\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. 24 mois\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le poids de naissance est doublé vers 3 mois (enfant au sein), triplé à 12 mois et multiplié par 4 à l'âge de 2 ans (24 mois).\\n\\nSource : Cours de santé infantile L1 IDE-SFM, « Mensurations », Repères de gain de poids\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J7 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j7-sf3__13\",\n       \"num\": \"14\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'âge recommandé par l'OMS pour débuter le sevrage du nourrisson est :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"24 mois\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"18 mois\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"16 mois\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"6 mois\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. 6 mois\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"L'OMS recommande l'allaitement exclusif jusqu'à 6 mois, puis l'introduction des aliments de complément à partir de 6 mois : c'est le début du sevrage, qui doit être progressif. Remarque : le cours précise que le sevrage complet se fait à 2 ans ; 6 mois correspond au début de la diversification.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Allaitement maternel », Modalités recommandées\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J7 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j7-sf3__14\",\n       \"num\": \"15\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'enfant à terme, eutrophique, nourri au sein exclusivement a comme acquisition à l'âge de 3 mois :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"réflexes archaïques présents\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"dirige son regard dans les deux directions\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"a peur de l'étranger\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"s'assoit seul\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. dirige son regard dans les deux directions\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"À 3 mois, le nourrisson tient sa tête dans l'axe, sourit et suit du regard (dirige son regard des deux côtés). La peur de l'étranger apparaît vers 8-9 mois et la station assise seule vers 6-8 mois ; les réflexes archaïques disparaissent vers le 3e mois.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), Annexes « Normes physiologiques de l'enfant », Principales étapes du développement psychomoteur\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J7 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j7-sf3__15\",\n       \"num\": \"16\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'objectif visé par le pédiatre lorsque la gestante réalise l'échographie du premier trimestre est de :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Estimer le risque d'hypoglycémie\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Rechercher une malformation du fœtus\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Vérifier la présence d'une activité cardiaque\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Rechercher un retard de croissance intra-utérin\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Vérifier la présence d'une activité cardiaque\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"L'échographie du 1er trimestre sert à confirmer la grossesse, la dater et vérifier l'activité cardiaque de l'embryon ; la recherche des malformations se fait surtout au 2e trimestre et le RCIU au 3e trimestre. (explication hors cours du projet)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J7 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j7-sf3__16\",\n       \"num\": \"17\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La fièvre élevée désigne l'élévation de la température corporelle prise par voie rectale, le matin à distance des repas, comprise entre :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"37,5 et 38,5 °C\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"38,5 et 40 °C\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"40 et 41 °C\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"36,5 et 37,5 °C\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. 38,5 et 40 °C\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La fièvre est une température supérieure à 37,5 °C le matin ; on la classe selon le degré. Entre 38,5 et 40 °C, la fièvre est élevée ; au-delà de 40 °C on parle d'hyperthermie majeure.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Fièvre de l'enfant », Définition et Diagnostic positif\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J7 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j7-sf3__17\",\n       \"num\": \"18\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Cocher parmi les signes paracliniques suivants celui qui est un critère de gravité du paludisme grave :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Hypocalcémie\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Hypoglycémie\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Thrombopénie sévère\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Hyperleucocytose\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Hypoglycémie\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"L'hypoglycémie fait partie des critères biologiques de gravité du paludisme définis par l'OMS (avec l'acidose, l'anémie sévère, l'hyperparasitémie, l'insuffisance rénale…). L'hypocalcémie et l'hyperleucocytose n'en font pas partie.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Paludisme de l'enfant », Paludisme grave – Manifestations biologiques\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J7 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j7-sf3__18\",\n       \"num\": \"19\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La diarrhée aiguë du nourrisson est définie par l'émission, par 24 heures, depuis moins de 14 jours, d'au moins :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"2 selles molles et liquides\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"3 selles molles et liquides\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"4 selles molles et liquides\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"5 selles molles et liquides\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. 3 selles molles et liquides\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La diarrhée aiguë se définit par l'émission d'au moins 3 selles molles ou liquides par 24 heures depuis moins de 14 jours.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Diarrhée aiguë et déshydratation de l'enfant », Définition ; Les 12 pratiques familiales essentielles (PFE), PFE n° 9\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J7 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j7-sf3__19\",\n       \"num\": \"20\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les selles de la diarrhée aiguë provoquée par Shigella sont :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"pâteuses sans glaires ni sang\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"liquides avec des selles\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"liquides sans selles\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"pâteuses avec des glaires et du sang\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. pâteuses avec des glaires et du sang\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"Shigella agit par mécanisme invasif : il détruit l'entérocyte et donne des selles glairo-sanglantes (dysenterie).\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Diarrhée aiguë et déshydratation de l'enfant », Pathogénie – Mécanisme invasif\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J7 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j7-sf3__20\",\n       \"num\": \"21\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le principal germe de la diarrhée aiguë virale du nourrisson est :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Coronavirus\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Entérovirus\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Rhinovirus\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Rotavirus\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. Rotavirus\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"Les causes infectieuses de diarrhée aiguë sont dominées par les virus, et parmi eux par le rotavirus.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Diarrhée aiguë et déshydratation de l'enfant », Etiologie – Causes infectieuses digestives\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J7 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j7-sf3__21\",\n       \"num\": \"22\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les avantages des soins mère-kangourou listés ci-après se trouve un intrus. Cochez l'intrus.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Favorise la prise de poids du nouveau-né\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Favorise l'équilibre thermique du nouveau-né\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Augmente la charge de travail du personnel\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Renforce la confiance de la mère\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Augmente la charge de travail du personnel\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"La méthode kangourou favorise l'équilibre thermique, la prise de poids et l'allaitement, et renforce la confiance de la mère. Elle n'augmente pas la charge de travail : la mère devient la principale dispensatrice de soins.\\n\\nSource : Module de néonatologie (Néonatalogie), Chapitre XVII « La méthode des soins mère kangourou », Avantages des SMK\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J7 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j7-sf3__22\",\n       \"num\": \"23\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les paramètres suivants sont les composants de la méthode de soins mère-kangourou sauf un. Cochez l'intrus.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Aider bébé à respirer\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Allaitement\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Suivi\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Contact peau à peau\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Aider bébé à respirer\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La méthode kangourou repose sur le contact peau à peau, l'allaitement maternel exclusif et le suivi du bébé. « Aider bébé à respirer » relève de la réanimation, pas des composantes de la méthode.\\n\\nSource : Module de néonatologie (Néonatalogie), Chapitre XVII « La méthode des soins mère kangourou », Définition\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J7 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j7-sf3__23\",\n       \"num\": \"24\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le débit d'oxygène du nouveau-né normal hospitalisé pour détresse respiratoire est compris entre :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"1 et 2 L/min\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"1 et 3 L/min\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"0,5 et 1 L/min\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"1 et 1,5 L/min\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. 0,5 et 1 L/min\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Si la saturation reste basse après la réanimation, on donne l'oxygène à 0,5 l/min chez le prématuré et 1 l/min chez le nouveau-né à terme, soit entre 0,5 et 1 l/min. Remarque : le cours du Dr Asse indique 1 à 2 l/min aux lunettes en milieu spécialisé ; la correction suit le module de néonatologie.\\n\\nSource : Module de néonatologie (Néonatalogie), Chapitre III « Réanimation en salle de naissance », Ventilation en pression positive\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J7 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j7-sf3__24\",\n       \"num\": \"25\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le principal germe responsable de la bronchiolite aiguë du nourrisson est le :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Virus respiratoire syncytial\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Rhinovirus\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Coronavirus\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Paramyxovirus\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Virus respiratoire syncytial\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La bronchiolite du nourrisson est une infection virale dont le principal germe est le virus respiratoire syncytial (VRS).\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Infections respiratoires aiguës de l'enfant », Principales formes étiologiques des IRA basses – Bronchiolite\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J7 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j7-sf3__25\",\n       \"num\": \"26\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans la maladie hémorragique du nouveau-né :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"La race blanche est un facteur favorisant\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"L'allaitement est un facteur favorisant\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"L'accouchement facile est un facteur favorisant\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Le lait artificiel est un facteur favorisant\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. L'allaitement est un facteur favorisant\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La maladie hémorragique est due à une carence en vitamine K1. Le lait maternel est pauvre en vitamine K, ce qui fait de l'allaitement exclusif un facteur favorisant ; c'est la race noire (et non blanche) qui est citée, ainsi que l'accouchement dystocique (et non facile). Remarque : le cours ne cite pas l'allaitement parmi les facteurs ; la pauvreté du lait maternel en vitamine K relève de connaissances générales (explication partiellement hors cours du projet). Remarque : dans le sujet, l'option C est coupée sur deux lignes ; elle a été réunie.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Maladie hémorragique du nouveau-né », Facteurs étiologiques\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J7 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j7-sf3__26\",\n       \"num\": \"27\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Une femme rhésus positif accouchant d'un enfant rhésus négatif reçoit du sérum anti-D en intramusculaire.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le sérum anti-D est donné à la mère Rhésus NÉGATIF qui accouche d'un bébé Rhésus POSITIF, dans les 72 heures. Une mère Rhésus positif ne risque pas d'allo-immunisation anti-D : Faux.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Ictère du nouveau-né », Rôles préventifs\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J7 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j7-sf3__27\",\n       \"num\": \"28\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le nourrisson de 3 mois est capable de tenir sa tête dans l'axe.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"À 3 mois, le nourrisson tient droit la tête dans l'axe.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), Annexes, « Principales étapes du développement psychomoteur » (3 mois)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J7 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j7-sf3__28\",\n       \"num\": \"29\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"À 9 mois, le nourrisson est capable de faire bravo et au revoir.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Vers 9 mois, le nourrisson imite les gestes : il fait « bravo » et « au revoir », pointe du doigt et a la pince pouce-index. (explication partiellement hors cours du projet)\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), Annexes, « Principales étapes du développement psychomoteur »\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J7 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j7-sf3__29\",\n       \"num\": \"30\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'échographie du premier trimestre permet de savoir si le fœtus sera trisomique ou pas.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La correction nationale retient « Vrai » : l'échographie du 1er trimestre mesure la clarté nucale, qui sert au dépistage de la trisomie 21. (explication hors cours du projet) Remarque : la clarté nucale estime un risque ; le diagnostic de certitude de la trisomie nécessite un caryotype.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J7 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j7-sf3__30\",\n       \"num\": \"31\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le nouveau-né macrosome de sexe masculin a un poids en dessous de 4000 g.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le nouveau-né normal pèse entre 2500 et 4000 g ; le macrosome a un poids supérieur à 4000 g. Faux.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Nouveau-né normal », Diagnostic positif ; « Nouveau-né de mère diabétique », Informations du dossier obstétrical\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J7 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j7-sf3__31\",\n       \"num\": \"32\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La principale complication respiratoire du prématuré est la maladie des membranes hyalines.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La maladie des membranes hyalines est due à un déficit en surfactant lié à l'immaturité pulmonaire ; c'est la principale cause de détresse respiratoire du prématuré.\\n\\nSource : Module de néonatologie (Néonatalogie), Chapitre VIII « Prématurité », Complications respiratoires – Maladie des membranes hyalines\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J7 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j7-sf3__32\",\n       \"num\": \"33\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le prématuré avec signes de danger est pris en charge en unité de néonatologie.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le prématuré qui présente une détresse respiratoire ou un signe de danger est une urgence : il faut le référer immédiatement en milieu spécialisé (néonatologie).\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Nouveau-né prématuré », Rôles de soins curatifs – 2e possibilité\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J7 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j7-sf3__33\",\n       \"num\": \"34\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les nouveau-nés à terme eutrophiques présentent dans 30 à 40 % des cas un ictère en période néonatale.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"L'ictère néonatal est fréquent : il touche tous les prématurés et une grande partie des nouveau-nés à terme (environ 30 à 40 % ; le chiffre n'est pas lisible dans le texte du cours). (explication partiellement hors cours du projet)\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Ictère du nouveau-né », Intérêt\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J7 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j7-sf3__34\",\n       \"num\": \"35\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Pour traiter le paludisme grave, je prescris 9 doses de 2,4 mg/kg d'artésunate injectable en intraveineuse directe.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"L'artésunate injectable est le traitement de 1re intention du paludisme grave : 2,4 mg/kg à H0, H12, H24 puis toutes les 24 heures, jusqu'à 9 doses maximum (7 jours). Remarque : le cours parle d'un « maximum » de 9 doses ; le relais oral est possible dès que l'enfant peut avaler.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Paludisme de l'enfant », Rôle de soins curatifs – 3e situation\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J7 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j7-sf3__35\",\n       \"num\": \"36\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le principal germe de l'infection materno-fœtale est le streptocoque B.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le streptocoque du groupe B est le principal germe de l'infection bactérienne précoce (materno-fœtale), devant E. coli.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Infections bactériennes du nouveau-né », Germes ; Module de néonatologie (Néonatalogie), Chapitre XII\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J7 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j7-sf3__36\",\n       \"num\": \"37\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le nourrisson de 9 mois manifeste de la peur devant un visage non familier.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Vers 8-9 mois apparaît l'angoisse (la peur) de l'étranger : le nourrisson manifeste de la peur devant un visage non familier.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Anorexie du nourrisson », Pathogénie de l'anorexie ; Annexes – développement psychomoteur\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J7 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j7-sf3__37\",\n       \"num\": \"38\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La déshydratation est une complication fréquente du marasme sévère.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Les principales complications de la malnutrition sévère sont l'hypoglycémie, la déshydratation (troubles digestifs) et les infections.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Malnutrition de l'enfant », Problèmes et devenir\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J7 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j7-sf3__38\",\n       \"num\": \"39\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'association ceftriaxone + aminoside est l'antibiotique probabiliste de première intention pour traiter l'infection bactérienne néonatale précoce.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Pour l'infection précoce, les germes (streptocoque B, E. coli) sont sensibles à l'amoxicilline : le traitement probabiliste associe amoxicilline (ou ampicilline) + aminoside. Faux.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Infections bactériennes du nouveau-né », Germes et Rôles curatifs ; Module de néonatologie (Néonatalogie), Chapitre XII, Traitement\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J7 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j7-sf3__39\",\n       \"num\": \"40\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'infection bactérienne néonatale précoce est favorisée par les gestes septiques de l'agent de santé lors de l'accouchement.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"L'infection précoce se contamine à partir de la mère (voie hématogène ou basse, réservoir vagino-urinaire). La contamination par les mains sales et les objets souillés par le personnel caractérise l'infection tardive. Faux. Remarque : le cours demande aussi de réaliser l'accouchement avec asepsie pour prévenir l'infection.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Infections bactériennes du nouveau-né », Mode de contamination\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J7 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j7-sf3__40\",\n       \"num\": \"41\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Pour reconnaître le paludisme simple au centre de santé urbain, je réalise au lit du client une goutte épaisse et un frottis sanguin.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Au centre de santé, le paludisme simple se confirme au lit du malade par le test de diagnostic rapide (TDR). La goutte épaisse et le frottis sont des examens de laboratoire, pas des tests réalisés au lit. Faux. (explication partiellement hors cours du projet)\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Paludisme de l'enfant », Examen para clinique\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J7 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j7-sf3__41\",\n       \"num\": \"42\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le nouveau-né normal a un temps de recoloration cutané de 5 secondes.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le temps de recoloration cutanée normal est inférieur à 3 secondes ; un TRC > 3 secondes est pathologique. Faux.\\n\\nSource : Module de néonatologie (Néonatalogie), Chapitre IV « Examen clinique du nouveau-né », Evaluation des constantes\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J7 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j7-sf3__42\",\n       \"num\": \"43\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le nourrisson présentant une déshydratation modérée est capable de boire.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Dans la déshydratation modérée (signes évidents), l'enfant est assoiffé et boit avec avidité ; c'est dans la forme sévère qu'il boit à peine ou est incapable de boire.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Diarrhée aiguë et déshydratation de l'enfant », Diagnostic de gravité (tableau)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J7 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j7-sf3__43\",\n       \"num\": \"44\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le nouveau-né normal a une coloration rouge brun.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le nouveau-né normal a une coloration rose. Faux.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Nouveau-né normal », Informations à rechercher à l'examen physique\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J7 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j7-sf3__44\",\n       \"num\": \"45\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'urée et la créatinine du sang font partie du bilan prénatal recommandé.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le bilan prénatal comprend groupe sanguin-rhésus, test d'Emmel ou électrophorèse de l'hémoglobine, VDRL/TPHA, glycémie, sérologie VIH (et ECBU, hépatite B, toxoplasmose, rubéole souhaités). L'urée et la créatinine n'en font pas partie. Faux.\\n\\nSource : Module de néonatologie (Néonatalogie), Chapitre IV « Soins essentiels aux nouveau-nés », Soins maternels\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J7 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j7-sf3__45\",\n       \"num\": \"46\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le nourrisson de 2 mois allaité au sein émettant 3 à 4 selles molles par 24 heures est atteint de diarrhée.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le nourrisson au sein émet normalement des selles molles fréquentes (jusqu'à 6 à 7 par jour) : ce sont de « fausses diarrhées ». 3 à 4 selles molles ne sont pas une diarrhée. Faux.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Diarrhée aiguë et déshydratation de l'enfant », Diagnostic différentiel ; Les 12 pratiques familiales essentielles (PFE), PFE n° 9\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J7 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j7-sf3__46\",\n       \"num\": \"47\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le plan A de traitement de la diarrhée est indiqué pour la diarrhée sans signes de déshydratation.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le plan A (traitement à domicile) s'applique quand il n'y a pas de signes de déshydratation.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Diarrhée aiguë et déshydratation de l'enfant », Réhydratation\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J7 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j7-sf3__47\",\n       \"num\": \"48\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Lors de la diarrhée aiguë, le nourrisson de 3 mois reçoit, en plus de la réhydratation et de l'alimentation, un comprimé de zinc dosé à 20 mg par jour pendant 10 jours.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Avant 6 mois, le zinc se donne à ½ comprimé de 20 mg, soit 10 mg par jour pendant 10 à 14 jours ; 20 mg/j (1 comprimé) est la dose à partir de 6 mois. Faux.\\n\\nSource : Livret de tableaux PCIMNE 0-5 ans, « Plan A », Donner du zinc\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J7 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j7-sf3__48\",\n       \"num\": \"49\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le nourrisson souffrant d'une diarrhée avec signes évidents de déshydratation est traité pendant les 4 premières heures au centre de santé.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Signes évidents de déshydratation : plan B, réhydratation par SRO au centre de santé pendant 4 heures, puis réévaluation.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Diarrhée aiguë et déshydratation de l'enfant », Réhydratation – Plan B\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J7 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j7-sf3__49\",\n       \"num\": \"50\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Au cours de la diarrhée aiguë, le tube digestif conserve 50 à 70 % de sa capacité d'absorption et de digestion des nutriments.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Pendant la diarrhée aiguë, l'intestin garde 50 à 70 % de sa capacité d'absorption ; c'est pourquoi il faut continuer d'alimenter l'enfant pour éviter la malnutrition.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Diarrhée aiguë et déshydratation de l'enfant », Pathogénie – Conséquences\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J7 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j7-sf3__50\",\n       \"num\": \"51\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le nouveau-né prématuré âgé de 36 semaines d'aménorrhée, stable, est pris en charge au centre de santé rural.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le prématuré apparemment sain (sans détresse respiratoire, teint rose) est pris en charge au centre de santé de 1er contact sans référence : mensurations, soins, vitamine K1, mise au sein, BCG, quand revenir.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Nouveau-né prématuré », Rôles de soins curatifs – 1re situation\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J7 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j7-sf3__51\",\n       \"num\": \"52\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Pour confirmer le diagnostic de l'avitaminose K1 chez le nouveau-né qui saigne, je collabore avec le médecin pour réaliser un groupe sanguin ABO/Rhésus.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"L'examen clé pour confirmer la carence en vitamine K1 est le temps de Quick, qui est allongé. Le groupe sanguin sert à la transfusion, pas au diagnostic. Faux.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Maladie hémorragique du nouveau-né », Informations à rechercher au laboratoire CORRIGÉ EXPLIQUÉ — PRÉPA DE INFAS\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J7 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      }\n     ]\n    }\n   ]\n  }\n ]\n}";
